package io.github.deepseekbridge;

import android.app.Application;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk={26,33},manifest=Config.NONE,application=Application.class)
public class ManagedTasksTest {
    final List<ManagedTasks> managers=new ArrayList<>();
    ManagedTasks manager(ManagedTasks.Launcher launcher){ManagedTasks m=new ManagedTasks(launcher,()->{});managers.add(m);return m;}
    @After public void cleanup(){for(ManagedTasks m:managers)m.close();}
    static JSONObject args(String command)throws Exception{return new JSONObject().put("command",command).put("wait_ms",0);}
    static class Fake implements ManagedTasks.Child {
        final CountDownLatch done=new CountDownLatch(1);int normal,forced,code;InputStream out=new ByteArrayInputStream(new byte[0]),err=new ByteArrayInputStream(new byte[0]);boolean ignoreNormal;
        public InputStream stdout(){return out;}public InputStream stderr(){return err;}public int pid(){return 42;}public int await()throws Exception{done.await();return code;}public void stop(boolean force){if(force)forced++;else normal++;if(force||!ignoreNormal)done.countDown();}
    }
    static String read(InputStream stream)throws Exception{try(InputStream in=stream;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[2048];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
    static String python()throws Exception{String configured=System.getProperty("studio.testPython");if(configured!=null)return configured;Process discover=new ProcessBuilder(System.getProperty("os.name").toLowerCase().contains("win")?"py.exe":"python3","-c","import sys;print(sys.executable)").start();String result=read(discover.getInputStream()).trim();if(discover.waitFor()!=0||result.isEmpty())throw new IOException("Python runtime required for actual persistent HTTP regression");return result;}
    @Test public void realHttpServerSurvivesTheStartCallAndIndependentRequestsThenStops()throws Exception{
        String executable=python();String script="import http.server\nclass H(http.server.BaseHTTPRequestHandler):\n def do_GET(self):\n  self.send_response(200);self.end_headers();self.wfile.write(b'MANAGED_HTTP_OK')\n def log_message(self,*args): pass\ns=http.server.HTTPServer(('127.0.0.1',0),H)\nprint('PORT='+str(s.server_port),flush=True)\ns.serve_forever()";
        ManagedTasks m=manager((p,c,w)->{final Process process=new ProcessBuilder(executable,"-u","-c",script).start();return new ManagedTasks.Child(){public InputStream stdout(){return process.getInputStream();}public InputStream stderr(){return process.getErrorStream();}public int pid(){return 1;}public int await()throws Exception{return process.waitFor();}public void stop(boolean force){if(force)process.destroyForcibly();else process.destroy();}};});
        JSONObject first=m.start("real-http","p-http",args("foreground HTTP fixture"));assertEquals("running",first.getString("state"));String output="";long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(System.nanoTime()<deadline){output=m.status("p-http","real-http").getString("stdout");if(output.contains("PORT="))break;Thread.sleep(20);}assertTrue(output,output.contains("PORT="));int port=Integer.parseInt(output.substring(output.indexOf("PORT=")+5).trim());URL url=new URL("http://127.0.0.1:"+port+"/");
        for(int i=0;i<2;i++){HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setConnectTimeout(1000);connection.setReadTimeout(1000);try{assertEquals(200,connection.getResponseCode());assertEquals("MANAGED_HTTP_OK",read(connection.getInputStream()));}finally{connection.disconnect();}assertEquals("running",m.status("p-http","real-http").getString("state"));}
        assertEquals("exited",m.stop("p-http","real-http").getString("state"));assertEquals(0,m.activeCount());HttpURLConnection stopped=(HttpURLConnection)url.openConnection();stopped.setConnectTimeout(500);try{stopped.getResponseCode();fail("server still accepts requests after stop");}catch(IOException expected){}finally{stopped.disconnect();}
    }
    @Test public void sameStartIdReplaysWithoutLaunchingAgainAndConflictsAreRejected()throws Exception{AtomicInteger launches=new AtomicInteger();Fake child=new Fake();ManagedTasks m=manager((p,c,w)->{launches.incrementAndGet();return child;});JSONObject a=args("python3 -m http.server 8899");m.start("once","p-a",a);m.start("once","p-a",a);assertEquals(1,launches.get());assertEquals(0,child.normal);try{m.start("once","p-a",args("other command"));fail("conflict accepted");}catch(IOException expected){}m.stop("p-a","once");m.start("once","p-a",a);assertEquals(1,launches.get());}
    @Test public void projectOwnershipAndFourTaskLimitApplyAndUnknownTasksNeverRestart()throws Exception{AtomicInteger launches=new AtomicInteger();ManagedTasks m=manager((p,c,w)->{launches.incrementAndGet();return new Fake();});for(int i=0;i<4;i++)m.start("job"+i,"p-a",args("foreground"));assertEquals(4,m.activeCount());try{m.start("overflow","p-b",args("foreground"));fail("limit ignored");}catch(IOException expected){}assertEquals(0,m.list("p-b").getJSONArray("jobs").length());try{m.stop("p-b","job0");fail("foreign stop accepted");}catch(IOException expected){}try{m.status("p-a","old-process-from-dead-app");fail("unknown process accepted");}catch(IOException expected){}assertEquals(4,launches.get());}
    @Test public void logTailsAreBoundedAndExitCodesAndStderrRemainVisible()throws Exception{Fake child=new Fake();byte[] text=new byte[180000];Arrays.fill(text,(byte)'x');byte[] end="LOG_END".getBytes(StandardCharsets.UTF_8);System.arraycopy(end,0,text,text.length-end.length,end.length);child.out=new ByteArrayInputStream(text);child.err=new ByteArrayInputStream("a real failure".getBytes(StandardCharsets.UTF_8));child.code=7;child.done.countDown();ManagedTasks m=manager((p,c,w)->child);JSONObject result=m.start("logs","p-a",args("failing fixture").put("wait_ms",2000));assertEquals("exited",result.getString("state"));assertEquals(7,result.getInt("exitCode"));assertTrue(result.getBoolean("truncated"));assertEquals(16384,result.getString("stdout").length());assertTrue(result.getString("stdout").endsWith("LOG_END"));assertEquals("a real failure",result.getString("stderr"));assertFalse(m.list("p-a").getJSONArray("jobs").getJSONObject(0).has("stdout"));assertTrue(m.list("p-a",true).getJSONArray("jobs").getJSONObject(0).has("stdout"));m.stop("p-a","logs");assertEquals(0,child.normal);}
    @Test public void previewUrlsAndFailedLaunchesDoNotIntroduceRemoteOrPhantomTasks()throws Exception{assertEquals("http://127.0.0.1:8899/",ManagedTasks.preview("http://127.0.0.1:8899/"));assertEquals("http://localhost:5173/",ManagedTasks.preview("http://localhost:5173/"));for(String url:new String[]{"https://example.com/","http://example.com:8899/","http://user@localhost:8899/","file:///private","http://127.0.0.1/"})try{ManagedTasks.preview(url);fail("unsafe preview accepted");}catch(IOException expected){}ManagedTasks m=manager((p,c,w)->{throw new IOException("spawn failed");});try{m.start("failed","p-a",args("server"));fail("failed spawn accepted");}catch(IOException expected){}assertEquals(0,m.activeCount());assertEquals(0,m.list("p-a").getJSONArray("jobs").length());}
    @Test public void closingDuringASlowLaunchReturnsImmediatelyAndStillCleansTheNewChild()throws Exception{CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);Fake child=new Fake();ManagedTasks m=manager((p,c,w)->{entered.countDown();release.await();return child;});java.util.concurrent.atomic.AtomicReference<Throwable> result=new java.util.concurrent.atomic.AtomicReference<>();Thread start=new Thread(()->{try{m.start("launching","p-a",args("server"));}catch(Throwable e){result.set(e);}});start.start();assertTrue(entered.await(2,TimeUnit.SECONDS));long before=System.nanoTime();m.close();assertTrue(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-before)<250);release.countDown();start.join(2000);assertFalse(start.isAlive());assertTrue(result.get() instanceof IOException);assertTrue(child.done.await(3,TimeUnit.SECONDS));}
    @Test public void closingNeverBlocksTheUiAndEscalatesAnUnresponsiveChild()throws Exception{Fake child=new Fake();child.ignoreNormal=true;ManagedTasks m=manager((p,c,w)->child);m.start("stubborn","p-a",args("foreground"));long start=System.nanoTime();m.close();assertTrue(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start)<250);assertTrue(child.done.await(5,TimeUnit.SECONDS));assertTrue(child.forced>0);try{m.start("after-close","p-a",args("foreground"));fail("closed manager launched task");}catch(IOException expected){}}
}
